import{_ as o,o as d,c as t,a0 as c}from"./chunks/framework.DhQjJcnt.js";const u=JSON.parse('{"title":"Skill: /docs-hub — bộ docs (tra cứu & CLI)","description":"","frontmatter":{},"headers":[],"relativePath":"references/skills/docs-hub.md","filePath":"references/skills/docs-hub.md"}'),a={name:"references/skills/docs-hub.md"};function r(l,e,i,n,s,p){return d(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="skill-docs-hub-—-bo-docs-tra-cuu-cli" tabindex="-1">Skill: <code>/docs-hub</code> — bộ docs (tra cứu &amp; CLI) <a class="header-anchor" href="#skill-docs-hub-—-bo-docs-tra-cuu-cli" aria-label="Permalink to &quot;Skill: `/docs-hub` — bộ docs (tra cứu &amp; CLI)&quot;">​</a></h1><h2 id="ten" tabindex="-1">Tên <a class="header-anchor" href="#ten" aria-label="Permalink to &quot;Tên&quot;">​</a></h2><p><strong>Bộ docs</strong> của FlowGrid — skill tra cứu Document Hub và các lệnh CLI <code>flowgrid split</code> / <code>render</code> / <code>publish</code>.</p><h2 id="cach-dung-command-trigger" tabindex="-1">Cách dùng (Command/Trigger) <a class="header-anchor" href="#cach-dung-command-trigger" aria-label="Permalink to &quot;Cách dùng (Command/Trigger)&quot;">​</a></h2><ul><li>Slash command: <strong><code>/docs-hub</code></strong> (index arc42/C4, routing ID, validate link).</li><li>CLI (repo Document Hub hoặc sau <code>flowgrid init</code>):</li></ul><table tabindex="0"><thead><tr><th>Việc</th><th>Lệnh</th><th>Alias <code>package.json</code> (sau init)</th></tr></thead><tbody><tr><td>Split một bundle</td><td><code>flowgrid split &lt;bundle.yaml&gt;</code></td><td><code>pnpm flowgrid:split</code></td></tr><tr><td>Split toàn repo</td><td><code>flowgrid split_all</code></td><td><code>pnpm flowgrid:split_all</code></td></tr><tr><td>Render spec MD</td><td><code>flowgrid render</code></td><td><code>pnpm flowgrid:render</code></td></tr><tr><td>Publish catalog</td><td><code>flowgrid publish</code></td><td><code>pnpm flowgrid:publish</code> / <code>pnpm flow:publish</code></td></tr></tbody></table><h2 id="mcp-server-flowgrid" tabindex="-1">MCP (server <code>flowgrid</code>) <a class="header-anchor" href="#mcp-server-flowgrid" aria-label="Permalink to &quot;MCP (server `flowgrid`)&quot;">​</a></h2><p>Nhóm tool <strong><code>flowgrid_docs_*</code></strong>: <code>flowgrid_docs_list_ids</code>, <code>flowgrid_docs_route</code>, <code>flowgrid_docs_get_element</code>, <code>flowgrid_docs_bundle_split</code>, <code>flowgrid_docs_docs_render</code>, …</p><p>Biến môi trường: <strong><code>FLOWGRID_DOCS_ROOT</code></strong> — đường dẫn tuyệt đối tới repo Document Hub (có <code>architecture/</code>).</p><h2 id="input-output" tabindex="-1">Input / Output <a class="header-anchor" href="#input-output" aria-label="Permalink to &quot;Input / Output&quot;">​</a></h2><ul><li><strong>split:</strong> <code>*.bundle.yaml</code> → <code>ir/design.yaml</code>, <code>ir/spec.yaml</code>, …</li><li><strong>render:</strong> <code>ir/*.yaml</code> → <code>ir/generated/*.md</code>, <code>qa/index.md</code></li><li><strong>publish:</strong> Markdown hiện có → <code>CATALOG.md</code> + link đầu <code>README.md</code></li></ul><h2 id="y-nghia" tabindex="-1">Ý nghĩa <a class="header-anchor" href="#y-nghia" aria-label="Permalink to &quot;Ý nghĩa&quot;">​</a></h2><ul><li>Bộ docs là SSOT kiến trúc &amp; spec; không trộn với symbol graph của repo code.</li><li><strong>Index routing:</strong> ID kiến trúc → bộ docs; symbol/call graph → CodeGraph repo tương ứng; gap/tag → ArtifactGraph local.</li><li>Authoring skills (<code>/spec</code>, <code>/grill-bqa</code>, …) kết thúc bằng <code>flowgrid split</code> (+ <code>render</code> khi cần review).</li></ul><h2 id="lien-quan" tabindex="-1">Liên quan <a class="header-anchor" href="#lien-quan" aria-label="Permalink to &quot;Liên quan&quot;">​</a></h2><ul><li><strong>Trước:</strong> <code>/spec</code>, <code>/update-spec</code>, <code>/api-spec</code>, …</li><li><strong>Sau:</strong> <code>flowgrid render</code> → <code>flowgrid dev</code> (VitePress)</li></ul><h2 id="chu-y" tabindex="-1">Chú ý <a class="header-anchor" href="#chu-y" aria-label="Permalink to &quot;Chú ý&quot;">​</a></h2><ul><li>Không sửa tay <code>ir/generated/*.md</code>; sửa bundle/IR rồi <code>split</code> + <code>render</code>.</li><li>Agent đọc <code>ir/design.yaml</code> sau split thay vì đọc cả <code>bundle.yaml</code> khổng lồ.</li></ul><hr><h2 id="example-prompt-mau-goi" tabindex="-1">Example prompt (mẫu gọi) <a class="header-anchor" href="#example-prompt-mau-goi" aria-label="Permalink to &quot;Example prompt (mẫu gọi)&quot;">​</a></h2><p><strong>Quy tắc:</strong> một session = một command · chat mới khi đổi phase · cập nhật <code>.harness/progress.md</code> nếu có.</p><p><strong>Khi nào:</strong> Gọi khi scope khớp mô tả skill ở trên.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/docs-hub</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Surface: {admin-web} · Module: {CMP-…} · Scope: {mô tả ngắn}</span></span></code></pre></div>',22)])])}const g=o(a,[["render",r]]);export{u as __pageData,g as default};
